		return this.chunks
			.map((chunk: Node) => {
				if (chunk.type === 'Text') {
					return escapeTemplate(escape(chunk.data).replace(/"/g, '&quot;'));
				}

				return '${@escape(' + chunk.snippet + ')}';
			})
			.join('');
	}
